parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Alert triage agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize alert').item.json;
const a = $json; // fresh read of the alert with transactions, screening and prior alert count
const d = out?.disposition;
const txns = a.transactions ?? [];
const txnIds = new Set(txns.map((t) => String(t.id)));
const total = Math.round(txns.reduce((s, t) => s + Number(t.amount ?? 0), 0) * 100) / 100;
const screeningHit = !!(a.screening?.sanctions_match || a.screening?.pep_match);
const priorAlerts = Number(a.prior_alert_count_365d ?? 0);
const indicators = out?.risk_indicators ?? [];

if (!['open', 'in_review'].includes(a.status)) reasons.push('alert status is now ' + a.status);
if (a.customer_ref && a.customer_ref !== req.customer_ref) reasons.push('alert customer ref on record differs from the event');
if (!txns.length) reasons.push('alert has no flagged transactions on record');
if (out && Math.abs(Number(out.total_flagged_amount) - total) > 0.01) reasons.push('agent flagged total ' + out.total_flagged_amount + ' differs from the transactions on record ' + total);
if (d === 'close') {
  if (!out?.close_reason) reasons.push('close recommended without a close reason');
  if (screeningHit) reasons.push('sanctions or PEP match on the alert; it cannot be closed by recommendation');
  if (priorAlerts >= cfg.repeat_alert_threshold) reasons.push(priorAlerts + ' prior alerts in 365 days (threshold ' + cfg.repeat_alert_threshold + '); a person decides whether to close');
}
if (d === 'escalate' || d === 'file') {
  if (!indicators.length) reasons.push(d + ' recommended without risk indicators');
  if (indicators.some((i) => !(i.evidence_ids ?? []).length)) reasons.push('a risk indicator cites no evidence ids');
  const cited = indicators.flatMap((i) => i.evidence_ids ?? []).map(String);
  if (indicators.length && !cited.some((id) => txnIds.has(id))) reasons.push('no risk indicator cites a flagged transaction on this alert');
}
if (d === 'file' && total < cfg.sar_min_amount) reasons.push('file recommended for a flagged total of ' + total + ', below ' + cfg.sar_min_amount + '; a person decides');

const action = {
  type: 'disposition_alert',
  alert_id: req.alert_id,
  disposition: d,
  case_status: d === 'close' ? 'closed' : d === 'escalate' ? 'escalated' : 'sar_pending',
  close_reason: d === 'close' ? out?.close_reason ?? null : null,
  typologies: out?.typologies ?? [],
  evidence_ids: indicators.flatMap((i) => i.evidence_ids ?? []),
  total_flagged_amount: total,
};
// Ids, counts and the recommendation only: Slack never carries customer or transaction detail.
const summary = 'Alert ' + req.alert_id + ' (' + req.scenario_code + ') · ' + txns.length + ' flagged transactions · ' + priorAlerts + ' prior alerts in 365 days'
  + (screeningHit ? ' · screening match on record' : '') + '.\n'
  + 'Proposed: *' + d + '*' + (d === 'close' ? ' (' + out?.close_reason + ')' : '') + (d === 'file' ? ' (marks for the SAR process; nothing is filed)' : '') + '.\n'
  + indicators.length + ' risk indicators with evidence. Full reasoning is in the case manager and the audit log.';
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : 'approve';
return { json: { business_key: req.business_key, route, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const ok = $json.status === planned.case_status && $json.disposition === planned.disposition && !$json.sar_filed;
const detail = 'alert shows status ' + $json.status + ' and disposition ' + $json.disposition + ', expected ' + planned.case_status + '/' + planned.disposition + ($json.sar_filed ? '; a SAR filing flag is set, which this agent never does' : '');
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize alert').item.json;
let agent = null;
let guard = null;
try { agent = $('Alert triage agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "AML operations",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Alert ' + intake.alert_id + ' · ' + intake.scenario_code + ' · proposed ' + (agent?.output?.disposition ?? 'none'),
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

parameters.jsCode:
const intake = $('Normalize alert').item.json;
let agent = null;
let guard = null;
let approval = null;
try { agent = $('Alert triage agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}
// Present only on workflows with a named-approver step, and only if this run reached it.
try { approval = $('Record approval').item.json; } catch (e) {}

return {
  json: {
    business_key: intake.business_key,
    outcome: $json.outcome,
    approval: approval ? { decision: approval.decision, approver: approval.approver, decided_at: approval.decided_at } : null,
    route: guard?.route ?? 'escalate',
    decision: agent?.output ?? null,
    guardrail_reasons: guard?.guardrail_reasons ?? [],
    actions: guard?.planned_actions ?? [],
    tool_calls: (agent?.intermediateSteps ?? []).length,
  },
};
